create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz default now());
create table public.projects (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null, description text, created_at timestamptz default now());
create table public.prompts (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, project_id uuid references public.projects(id) on delete set null, title text not null, content text not null, created_at timestamptz default now());
create table public.tasks (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, project_id uuid references public.projects(id) on delete set null, title text not null, instructions text not null, status text not null default 'draft' check(status in ('draft','queued','running','succeeded','failed','cancelled')), claimed_by uuid, claimed_at timestamptz, created_at timestamptz default now());
create table public.files (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, project_id uuid references public.projects(id) on delete set null, storage_path text not null unique, name text not null, mime_type text, size bigint, created_at timestamptz default now());
create table public.workers (id uuid primary key, name text not null, status text not null default 'online', last_seen_at timestamptz default now());
create table public.task_runs (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade, worker_id uuid references public.workers(id), status text not null default 'running', started_at timestamptz default now(), finished_at timestamptz, exit_code integer, output_text text, error_text text);
create table public.task_outputs (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade, run_id uuid references public.task_runs(id) on delete set null, owner_id uuid not null references auth.users(id) on delete cascade, content text not null, created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.projects enable row level security; alter table public.prompts enable row level security; alter table public.tasks enable row level security; alter table public.files enable row level security; alter table public.task_runs enable row level security; alter table public.task_outputs enable row level security; alter table public.workers enable row level security;
create policy "own profiles" on public.profiles for all using (id=auth.uid()) with check (id=auth.uid());
create policy "own projects" on public.projects for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "own prompts" on public.prompts for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "own tasks" on public.tasks for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "own files" on public.files for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "own runs" on public.task_runs for select using (exists(select 1 from public.tasks t where t.id=task_id and t.owner_id=auth.uid()));
create policy "own outputs" on public.task_outputs for select using (owner_id=auth.uid());
create policy "worker status visible" on public.workers for select using (auth.uid() is not null);
insert into storage.buckets (id,name,public) values ('task-files','task-files',false) on conflict do nothing;
create policy "own task files" on storage.objects for all using (bucket_id='task-files' and (storage.foldername(name))[1]=auth.uid()::text) with check (bucket_id='task-files' and (storage.foldername(name))[1]=auth.uid()::text);
create or replace function public.claim_next_task(p_worker_id uuid) returns table(task_id uuid, run_id uuid, title text, instructions text, owner_id uuid) language plpgsql security definer set search_path=public as $$ declare t public.tasks; r uuid; begin select * into t from public.tasks where status='queued' order by created_at for update skip locked limit 1; if not found then return; end if; update public.tasks set status='running',claimed_by=p_worker_id,claimed_at=now() where id=t.id; insert into public.task_runs(task_id,worker_id) values(t.id,p_worker_id) returning id into r; return query select t.id,r,t.title,t.instructions,t.owner_id; end; $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1))); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
